import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const {
    Group,
    Mesh,
    PlaneGeometry,
    BoxGeometry,
    CircleGeometry,
    PointLight,
    DoubleSide
  } = THREE;

  const root = new Group();
  root.name = 'nova-thumbnail-card';
  root.userData.handlers = {};

  const timelines = [];
  const primitiveResults = [];
  const disposables = [];
  let disposed = false;

  const makeStandard = (color, options = {}) => {
    const material = new MeshStandardNodeMaterial();
    material.color = color;
    material.roughness = options.roughness ?? 0.62;
    material.metalness = options.metalness ?? 0.18;
    if ('emissive' in options) material.emissive = options.emissive;
    if ('emissiveIntensity' in options) {
      material.emissiveIntensity = options.emissiveIntensity;
    }
    return material;
  };

  const backdropMaterial = new MeshBasicNodeMaterial();
  backdropMaterial.colorNode = mix(
    vec3('#0b0b10'),
    vec3('#16161d'),
    smoothstep(0.05, 0.95, uv().y)
  );
  backdropMaterial.side = DoubleSide;

  const backdrop = new Mesh(new PlaneGeometry(7, 6), backdropMaterial);
  backdrop.name = 'designed-vertical-backdrop';
  backdrop.position.z = -2.5;
  root.add(backdrop);
  disposables.push(backdrop);

  const shadowMaterial = new MeshBasicNodeMaterial({
    color: '#0b0b10',
    transparent: true,
    opacity: 0.52,
    depthWrite: false
  });
  const contactShadow = new Mesh(
    new CircleGeometry(1.7, 48),
    shadowMaterial
  );
  contactShadow.name = 'thumbnail-contact-shadow';
  contactShadow.rotation.x = -Math.PI / 2;
  contactShadow.position.set(0, -1.08, -0.18);
  contactShadow.scale.set(1.35, 0.58, 1);
  root.add(contactShadow);
  disposables.push(contactShadow);

  const cardAssembly = new Group();
  cardAssembly.name = 'thumbnail-card-assembly';
  cardAssembly.position.y = 0.03;
  cardAssembly.scale.setScalar(0.985);
  root.add(cardAssembly);

  const cardBackingMaterial = makeStandard('#16161d', {
    roughness: 0.72,
    metalness: 0.24
  });
  const cardBacking = new Mesh(
    new BoxGeometry(3.18, 2.16, 0.12),
    cardBackingMaterial
  );
  cardBacking.name = 'machined-card-backing';
  cardBacking.position.z = -0.08;
  cardAssembly.add(cardBacking);
  disposables.push(cardBacking);

  const imageOpeningMaterial = makeStandard('#0b0b10', {
    roughness: 0.66,
    metalness: 0.12
  });
  const imageOpening = new Mesh(
    new BoxGeometry(2.9, 1.72, 0.06),
    imageOpeningMaterial
  );
  imageOpening.name = 'image-opening';
  imageOpening.position.set(0, 0.15, 0.01);
  cardAssembly.add(imageOpening);
  disposables.push(imageOpening);

  const stripMaterial = makeStandard('#16161d', {
    roughness: 0.58,
    metalness: 0.42
  });
  const captionStrip = new Mesh(
    new BoxGeometry(2.9, 0.4, 0.08),
    stripMaterial
  );
  captionStrip.name = 'caption-strip';
  captionStrip.position.set(0, -0.87, 0.04);
  cardAssembly.add(captionStrip);
  disposables.push(captionStrip);

  const accentMaterial = makeStandard('#ff2a38', {
    roughness: 0.5,
    metalness: 0.3,
    emissive: '#ff2a38',
    emissiveIntensity: 0.7
  });
  const accentEdge = new Mesh(
    new BoxGeometry(2.9, 0.035, 0.035),
    accentMaterial
  );
  accentEdge.name = 'focus-accent-edge';
  accentEdge.position.set(0, -0.665, 0.105);
  accentEdge.scale.x = 0.001;
  cardAssembly.add(accentEdge);
  disposables.push(accentEdge);

  const frameMaterial = makeStandard('#e8ecf2', {
    roughness: 0.56,
    metalness: 0.5
  });
  const framePieces = [
    [3.18, 0.045, 0.1, 0, 1.08, 0.08],
    [3.18, 0.045, 0.1, 0, -1.08, 0.08],
    [0.045, 2.16, 0.1, -1.59, 0, 0.08],
    [0.045, 2.16, 0.1, 1.59, 0, 0.08]
  ];

  for (const [sx, sy, sz, x, y, z] of framePieces) {
    const piece = new Mesh(
      new BoxGeometry(sx, sy, sz),
      frameMaterial
    );
    piece.position.set(x, y, z);
    piece.name = 'machined-card-frame';
    cardAssembly.add(piece);
    disposables.push(piece);
  }

  const rimLight = new PointLight('#ff2a38', 0.72, 5.5, 2);
  rimLight.position.set(2.2, 1.6, 2.4);
  root.add(rimLight);

  const fillLight = new PointLight('#e8ecf2', 0.42, 4.5, 2);
  fillLight.position.set(-2.4, 0.8, 2.8);
  root.add(fillLight);

  const subject = new Group();
  subject.name = 'gear-a-subject';
  subject.position.set(0, 0.1, 0.18);
  subject.scale.setScalar(1.05);
  cardAssembly.add(subject);

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    if (!item || typeof item.text !== 'string') continue;
    const textObject = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize ?? 28,
      color: item.role === 'caption' ? '#e8ecf2' : '#ff2a38',
      align: item.align ?? 'left',
      maxWidthPx: item.maxWidthPx ?? 380,
      letterSpacingPx: item.typography?.letterSpacingPx ?? 1
    });
    textObject.position.set(-1.22, -0.87, 0.1);
    cardAssembly.add(textObject);
    disposables.push(textObject);
  }

  cardAssembly.scale.setScalar(0.965);
  const entrance = gsap.timeline({ paused: false });
  entrance.to(cardAssembly.scale, {
    x: 1.004,
    y: 1.004,
    z: 1.004,
    duration: 0.42,
    ease: 'power3.out'
  }).to(cardAssembly.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.48,
    ease: 'power4.out'
  });
  timelines.push(entrance);

  const hoverTween = { y: 0.03, scale: 1 };
  const focusTween = { scale: 0.001 };

  root.userData.handlers.hover = (active = true) => {
    if (disposed) return;
    gsap.killTweensOf(hoverTween);
    const targetY = active ? 0.18 : 0.03;
    const targetScale = active ? 1.018 : 1;
    gsap.to(hoverTween, {
      y: targetY,
      scale: targetScale,
      duration: 0.3,
      ease: 'power3.out',
      onUpdate: () => {
        cardAssembly.position.y = hoverTween.y;
        cardAssembly.scale.setScalar(hoverTween.scale);
      }
    });
  };

  root.userData.handlers.focus = (active = true) => {
    if (disposed) return;
    gsap.killTweensOf(focusTween);
    gsap.to(focusTween, {
      scale: active ? 1 : 0.001,
      duration: 0.22,
      ease: 'power2.out',
      onUpdate: () => {
        accentEdge.scale.x = focusTween.scale;
      }
    });
  };

  root.userData.handlers.click = () => {
    if (disposed) return;
    const press = gsap.timeline();
    press.to(cardAssembly.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'power2.out'
    }).to(cardAssembly.scale, {
      x: 1.04,
      y: 1.04,
      z: 1.04,
      duration: 0.28,
      ease: 'back.out(2)'
    }).to(cardAssembly.scale, {
      x: 1,
      y: 1,
      z: 1,
      duration: 0.38,
      ease: 'power4.out'
    });
    timelines.push(press);
    ctx.emit('hub-home.select', {
      node: root.name,
      destination: 'hub-home'
    });
  };

  const primitives = config.cinematicPrimitives ?? [];
  for (const primitive of primitives) {
    const handler = ctx.primitives?.[primitive.name];
    if (typeof handler !== 'function') continue;
    const result = handler(root, primitive.params ?? {});
    if (result) {
      primitiveResults.push(result);
      if (result.timeline) timelines.push(result.timeline);
    }
  }

  if (config.meshUrl && ctx.glbLoader?.loadGLB) {
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      if (disposed || !gltf?.scene) return;
      const loadedScene = gltf.scene;
      loadedScene.name = 'gear-a-loaded-mesh';
      loadedScene.traverse((object) => {
        if (object.isMesh) {
          object.castShadow = true;
          object.receiveShadow = true;
        }
      });
      subject.add(loadedScene);
      disposables.push(loadedScene);
    }).catch(() => {});
  }

  root.userData.cleanup = () => {
    if (disposed) return;
    disposed = true;

    for (const timeline of timelines) {
      if (timeline?.kill) timeline.kill();
    }
    for (const result of primitiveResults) {
      if (result?.cleanup) result.cleanup();
    }

    root.traverse((object) => {
      if (object.geometry?.dispose) object.geometry.dispose();
      if (object.material) {
        const materials = Array.isArray(object.material)
          ? object.material
          : [object.material];
        for (const material of materials) {
          if (material?.dispose) material.dispose();
        }
      }
    });

    for (const disposable of disposables) {
      if (disposable.parent) disposable.parent.remove(disposable);
    }
  };

  return root;
}
